-- ============================================================================
-- SQL Server 2017+ 初始化脚本
-- 配套 complex-sql 300 条复杂业务 SQL 的初始化脚本（建表 + 测试数据）
-- ============================================================================
--
-- 说明：
--   1. 共 51 张表，94332 行测试数据。
--   2. 所有日期/时间列均以『当前时间』为基准动态生成相对偏移，
--      因此无论何时执行，近 30 天 / 180 天 / 1 年 / 3 年的分析窗口都有数据。
--   3. 数据刻意包含：帕累托分布的高价值客户、快进快出与拆分交易等可疑模式、
--      逾期贷款、考勤异常、少量 NULL 与重复姓名、少量孤儿外键记录，
--      用于让风控/数据质量/异常检测类 SQL 能跑出非空结果。
--   4. 表结构与字段说明见 README.md。
--   5. 建议执行前先创建数据库：CREATE DATABASE complex_sql; GO  USE complex_sql; GO
--
-- ============================================================================

SET NOCOUNT ON;

-- ---------- 1. 删除已存在的表 ----------
IF OBJECT_ID('payroll', 'U') IS NOT NULL DROP TABLE payroll;
IF OBJECT_ID('project_assignments', 'U') IS NOT NULL DROP TABLE project_assignments;
IF OBJECT_ID('projects', 'U') IS NOT NULL DROP TABLE projects;
IF OBJECT_ID('recruitment', 'U') IS NOT NULL DROP TABLE recruitment;
IF OBJECT_ID('training_records', 'U') IS NOT NULL DROP TABLE training_records;
IF OBJECT_ID('emp_changes', 'U') IS NOT NULL DROP TABLE emp_changes;
IF OBJECT_ID('performance', 'U') IS NOT NULL DROP TABLE performance;
IF OBJECT_ID('leave_requests', 'U') IS NOT NULL DROP TABLE leave_requests;
IF OBJECT_ID('leaves', 'U') IS NOT NULL DROP TABLE leaves;
IF OBJECT_ID('attendance', 'U') IS NOT NULL DROP TABLE attendance;
IF OBJECT_ID('salaries', 'U') IS NOT NULL DROP TABLE salaries;
IF OBJECT_ID('employees', 'U') IS NOT NULL DROP TABLE employees;
IF OBJECT_ID('departments', 'U') IS NOT NULL DROP TABLE departments;
IF OBJECT_ID('fin_reports', 'U') IS NOT NULL DROP TABLE fin_reports;
IF OBJECT_ID('fx_rates', 'U') IS NOT NULL DROP TABLE fx_rates;
IF OBJECT_ID('holdings', 'U') IS NOT NULL DROP TABLE holdings;
IF OBJECT_ID('fund_nav', 'U') IS NOT NULL DROP TABLE fund_nav;
IF OBJECT_ID('fund_products', 'U') IS NOT NULL DROP TABLE fund_products;
IF OBJECT_ID('risk_events', 'U') IS NOT NULL DROP TABLE risk_events;
IF OBJECT_ID('credit_scores', 'U') IS NOT NULL DROP TABLE credit_scores;
IF OBJECT_ID('deposits', 'U') IS NOT NULL DROP TABLE deposits;
IF OBJECT_ID('repayments', 'U') IS NOT NULL DROP TABLE repayments;
IF OBJECT_ID('loans', 'U') IS NOT NULL DROP TABLE loans;
IF OBJECT_ID('card_txns', 'U') IS NOT NULL DROP TABLE card_txns;
IF OBJECT_ID('cards', 'U') IS NOT NULL DROP TABLE cards;
IF OBJECT_ID('transactions', 'U') IS NOT NULL DROP TABLE transactions;
IF OBJECT_ID('accounts', 'U') IS NOT NULL DROP TABLE accounts;
IF OBJECT_ID('fin_customers', 'U') IS NOT NULL DROP TABLE fin_customers;
IF OBJECT_ID('branches', 'U') IS NOT NULL DROP TABLE branches;
IF OBJECT_ID('cust_level_log', 'U') IS NOT NULL DROP TABLE cust_level_log;
IF OBJECT_ID('user_events', 'U') IS NOT NULL DROP TABLE user_events;
IF OBJECT_ID('reviews', 'U') IS NOT NULL DROP TABLE reviews;
IF OBJECT_ID('promotions', 'U') IS NOT NULL DROP TABLE promotions;
IF OBJECT_ID('order_coupon', 'U') IS NOT NULL DROP TABLE order_coupon;
IF OBJECT_ID('coupons', 'U') IS NOT NULL DROP TABLE coupons;
IF OBJECT_ID('carts', 'U') IS NOT NULL DROP TABLE carts;
IF OBJECT_ID('wh_sales', 'U') IS NOT NULL DROP TABLE wh_sales;
IF OBJECT_ID('wh_stock', 'U') IS NOT NULL DROP TABLE wh_stock;
IF OBJECT_ID('inventory', 'U') IS NOT NULL DROP TABLE inventory;
IF OBJECT_ID('warehouses', 'U') IS NOT NULL DROP TABLE warehouses;
IF OBJECT_ID('logistics_nodes', 'U') IS NOT NULL DROP TABLE logistics_nodes;
IF OBJECT_ID('shipments', 'U') IS NOT NULL DROP TABLE shipments;
IF OBJECT_ID('refunds', 'U') IS NOT NULL DROP TABLE refunds;
IF OBJECT_ID('payments', 'U') IS NOT NULL DROP TABLE payments;
IF OBJECT_ID('order_items', 'U') IS NOT NULL DROP TABLE order_items;
IF OBJECT_ID('orders', 'U') IS NOT NULL DROP TABLE orders;
IF OBJECT_ID('customers', 'U') IS NOT NULL DROP TABLE customers;
IF OBJECT_ID('store_targets', 'U') IS NOT NULL DROP TABLE store_targets;
IF OBJECT_ID('stores', 'U') IS NOT NULL DROP TABLE stores;
IF OBJECT_ID('products', 'U') IS NOT NULL DROP TABLE products;
IF OBJECT_ID('categories', 'U') IS NOT NULL DROP TABLE categories;

-- ---------- 2. 建表 ----------
-- 商品品类 (categories)，主键：category_id
CREATE TABLE categories (
    category_id INT,
    category_name NVARCHAR(128),
    parent_category_id INT
);

-- 商品 (products)，主键：product_id
CREATE TABLE products (
    product_id INT,
    product_name NVARCHAR(128),
    category_id INT,
    brand NVARCHAR(128),
    price DECIMAL(18,2),
    cost DECIMAL(18,2),
    launch_date DATETIME2(0),
    status NVARCHAR(128)
);

-- 门店 (stores)，主键：store_id
CREATE TABLE stores (
    store_id INT,
    store_name NVARCHAR(128),
    city NVARCHAR(128),
    province NVARCHAR(128),
    region NVARCHAR(128),
    open_date DATETIME2(0),
    status NVARCHAR(128),
    dept_id INT
);

-- 门店月度目标 (store_targets)，主键：store_id, target_month
CREATE TABLE store_targets (
    store_id INT,
    target_month DATETIME2(0),
    target_amt DECIMAL(18,2),
    budget DECIMAL(18,2)
);

-- 电商客户 (customers)，主键：customer_id
CREATE TABLE customers (
    customer_id INT,
    customer_name NVARCHAR(128),
    gender NVARCHAR(128),
    birth_date DATETIME2(0),
    city NVARCHAR(128),
    province NVARCHAR(128),
    register_date DATETIME2(0),
    level NVARCHAR(128),
    status NVARCHAR(128),
    last_order_date DATETIME2(0),
    order_cnt INT,
    total_amt DECIMAL(18,2)
);

-- 订单主表 (orders)，主键：order_id
CREATE TABLE orders (
    order_id INT,
    customer_id INT,
    store_id INT,
    order_date DATETIME2(0),
    status NVARCHAR(128),
    channel NVARCHAR(128),
    pay_amount DECIMAL(18,2),
    discount_amount DECIMAL(18,2)
);

-- 订单明细 (order_items)，主键：order_id, product_id
CREATE TABLE order_items (
    order_id INT,
    product_id INT,
    quantity INT,
    amount DECIMAL(18,2),
    price DECIMAL(18,2)
);

-- 支付流水 (payments)，主键：payment_id
CREATE TABLE payments (
    payment_id INT,
    order_id INT,
    pay_method NVARCHAR(128),
    pay_amount DECIMAL(18,2),
    pay_date DATETIME2(0),
    pay_time DATETIME2(0),
    status NVARCHAR(128)
);

-- 退款记录 (refunds)，主键：refund_id
CREATE TABLE refunds (
    refund_id INT,
    order_id INT,
    refund_amount DECIMAL(18,2),
    refund_reason NVARCHAR(128),
    reason NVARCHAR(128),
    refund_date DATETIME2(0),
    status NVARCHAR(128)
);

-- 物流运单 (shipments)，主键：shipment_id
CREATE TABLE shipments (
    shipment_id INT,
    order_id INT,
    carrier NVARCHAR(128),
    ship_date DATETIME2(0),
    delivery_days INT,
    province NVARCHAR(128),
    city NVARCHAR(128),
    status NVARCHAR(128),
    last_node NVARCHAR(128),
    last_node_time DATETIME2(0)
);

-- 物流轨迹节点 (logistics_nodes)，主键：node_id
CREATE TABLE logistics_nodes (
    node_id INT,
    order_id INT,
    node_name NVARCHAR(128),
    node_time DATETIME2(0)
);

-- 仓库 (warehouses)，主键：warehouse_id
CREATE TABLE warehouses (
    warehouse_id INT,
    warehouse_name NVARCHAR(128),
    city NVARCHAR(128),
    province NVARCHAR(128),
    region NVARCHAR(128)
);

-- 库存 (inventory)，主键：product_id, warehouse_id
CREATE TABLE inventory (
    product_id INT,
    warehouse_id INT,
    stock_qty INT,
    quantity INT,
    safety_stock INT,
    safety_qty INT
);

-- 仓库库存快照 (wh_stock)，主键：warehouse_id, product_id
CREATE TABLE wh_stock (
    warehouse_id INT,
    product_id INT,
    stock_qty INT,
    safety_stock INT,
    safety_qty INT,
    sku_cnt INT
);

-- 仓库出库流水 (wh_sales)，主键：warehouse_id, product_id, sale_date
CREATE TABLE wh_sales (
    warehouse_id INT,
    product_id INT,
    qty_sold INT,
    amt_sold DECIMAL(18,2),
    sale_date DATETIME2(0)
);

-- 购物车 (carts)，主键：cart_id
CREATE TABLE carts (
    cart_id INT,
    customer_id INT,
    product_id INT,
    add_time DATETIME2(0),
    quantity INT,
    status NVARCHAR(128),
    is_purchased INT
);

-- 优惠券 (coupons)，主键：coupon_id
CREATE TABLE coupons (
    coupon_id INT,
    coupon_name NVARCHAR(128),
    coupon_type NVARCHAR(128),
    promo_id INT,
    face_value DECIMAL(18,2),
    issued_cnt INT,
    used_cnt INT,
    order_id INT,
    start_date DATETIME2(0),
    end_date DATETIME2(0),
    status NVARCHAR(128)
);

-- 订单用券 (order_coupon)，主键：order_id, coupon_id
CREATE TABLE order_coupon (
    order_id INT,
    coupon_id INT,
    promo_id INT,
    coupon_cnt INT,
    total_face DECIMAL(18,2)
);

-- 促销活动 (promotions)，主键：promo_id
CREATE TABLE promotions (
    promo_id INT,
    promo_name NVARCHAR(128),
    promo_type NVARCHAR(128),
    category_id INT,
    budget DECIMAL(18,2),
    start_date DATETIME2(0),
    end_date DATETIME2(0),
    discount_rate DECIMAL(12,6)
);

-- 商品评价 (reviews)，主键：review_id
CREATE TABLE reviews (
    review_id INT,
    order_id INT,
    product_id INT,
    customer_id INT,
    rating INT,
    content NVARCHAR(512),
    review_date DATETIME2(0),
    created_at DATETIME2(0)
);

-- 用户行为埋点 (user_events)，主键：event_id
CREATE TABLE user_events (
    event_id INT,
    customer_id INT,
    session_id NVARCHAR(128),
    event_type NVARCHAR(128),
    event_time DATETIME2(0),
    product_id INT,
    page NVARCHAR(128),
    page_url NVARCHAR(512),
    device NVARCHAR(128)
);

-- 会员等级变更 (cust_level_log)，主键：log_id
CREATE TABLE cust_level_log (
    log_id INT,
    customer_id INT,
    old_level NVARCHAR(128),
    new_level NVARCHAR(128),
    change_date DATETIME2(0),
    status NVARCHAR(128)
);

-- 分支行 (branches)，主键：branch_id
CREATE TABLE branches (
    branch_id INT,
    branch_name NVARCHAR(128),
    city NVARCHAR(128),
    region NVARCHAR(128),
    open_date DATETIME2(0),
    manager_id INT
);

-- 金融客户 (fin_customers)，主键：cust_id
CREATE TABLE fin_customers (
    cust_id INT,
    cust_name NVARCHAR(128),
    cust_type NVARCHAR(128),
    gender NVARCHAR(128),
    birth_date DATETIME2(0),
    city NVARCHAR(128),
    province NVARCHAR(128),
    register_date DATETIME2(0),
    risk_level NVARCHAR(128),
    branch_id INT,
    manager_id INT,
    status NVARCHAR(128)
);

-- 账户 (accounts)，主键：account_id
CREATE TABLE accounts (
    account_id INT,
    cust_id INT,
    branch_id INT,
    account_type NVARCHAR(128),
    balance DECIMAL(18,2),
    acct_balance DECIMAL(18,2),
    open_date DATETIME2(0),
    status NVARCHAR(128),
    currency NVARCHAR(128)
);

-- 交易流水 (transactions)，主键：txn_id
CREATE TABLE transactions (
    txn_id INT,
    account_id INT,
    cust_id INT,
    txn_date DATETIME2(0),
    txn_type NVARCHAR(128),
    amount DECIMAL(18,2),
    channel NVARCHAR(128),
    counterparty NVARCHAR(128),
    merchant NVARCHAR(128),
    mcc NVARCHAR(128),
    is_overseas INT,
    city NVARCHAR(128),
    card_id INT,
    balance_after DECIMAL(18,2)
);

-- 银行卡 (cards)，主键：card_id
CREATE TABLE cards (
    card_id INT,
    cust_id INT,
    account_id INT,
    card_type NVARCHAR(128),
    credit_limit DECIMAL(18,2),
    open_date DATETIME2(0),
    status NVARCHAR(128)
);

-- 卡交易 (card_txns)，主键：txn_id
CREATE TABLE card_txns (
    txn_id INT,
    card_id INT,
    txn_date DATETIME2(0),
    amount DECIMAL(18,2),
    merchant NVARCHAR(128),
    mcc NVARCHAR(128),
    is_overseas INT,
    city NVARCHAR(128),
    status NVARCHAR(128)
);

-- 贷款 (loans)，主键：loan_id
CREATE TABLE loans (
    loan_id INT,
    cust_id INT,
    branch_id INT,
    product_type NVARCHAR(128),
    loan_amount DECIMAL(18,2),
    interest_rate DECIMAL(12,6),
    term_months INT,
    start_date DATETIME2(0),
    end_date DATETIME2(0),
    maturity_date DATETIME2(0),
    status NVARCHAR(128),
    overdue_days INT,
    outstanding DECIMAL(18,2)
);

-- 还款流水 (repayments)，主键：repay_id
CREATE TABLE repayments (
    repay_id INT,
    loan_id INT,
    repay_date DATETIME2(0),
    due_date DATETIME2(0),
    amount DECIMAL(18,2),
    due_amount DECIMAL(18,2),
    paid_amount DECIMAL(18,2),
    principal DECIMAL(18,2),
    interest DECIMAL(18,2),
    status NVARCHAR(128),
    overdue_days INT
);

-- 存款 (deposits)，主键：deposit_id
CREATE TABLE deposits (
    deposit_id INT,
    cust_id INT,
    branch_id INT,
    account_id INT,
    deposit_amt DECIMAL(18,2),
    dep_amt DECIMAL(18,2),
    amount DECIMAL(18,2),
    rate DECIMAL(12,6),
    avg_rate DECIMAL(12,6),
    interest_rate DECIMAL(12,6),
    term_months INT,
    start_date DATETIME2(0),
    maturity_date DATETIME2(0),
    status NVARCHAR(128)
);

-- 信用评分 (credit_scores)，主键：score_id
CREATE TABLE credit_scores (
    score_id INT,
    cust_id INT,
    score INT,
    score_date DATETIME2(0),
    model_version NVARCHAR(128)
);

-- 风险事件 (risk_events)，主键：event_id
CREATE TABLE risk_events (
    event_id INT,
    cust_id INT,
    event_type NVARCHAR(128),
    risk_level NVARCHAR(128),
    risk_num INT,
    event_date DATETIME2(0),
    event_time DATETIME2(0),
    amount DECIMAL(18,2),
    status NVARCHAR(128)
);

-- 基金产品 (fund_products)，主键：fund_id
CREATE TABLE fund_products (
    fund_id INT,
    fund_name NVARCHAR(128),
    fund_type NVARCHAR(128),
    manager_id INT,
    manager_name NVARCHAR(128),
    launch_date DATETIME2(0),
    risk_level NVARCHAR(128),
    status NVARCHAR(128)
);

-- 基金净值 (fund_nav)，主键：fund_id, nav_date
CREATE TABLE fund_nav (
    fund_id INT,
    nav_date DATETIME2(0),
    nav DECIMAL(12,6),
    cur_nav DECIMAL(12,6),
    acc_nav DECIMAL(12,6)
);

-- 基金持仓 (holdings)，主键：hold_id
CREATE TABLE holdings (
    hold_id INT,
    cust_id INT,
    fund_id INT,
    shares DECIMAL(18,2),
    cost_amount DECIMAL(18,2),
    market_value DECIMAL(18,2),
    purchase_date DATETIME2(0)
);

-- 汇率 (fx_rates)，主键：rate_date, currency
CREATE TABLE fx_rates (
    rate_date DATETIME2(0),
    currency NVARCHAR(128),
    base_currency NVARCHAR(128),
    rate DECIMAL(12,6)
);

-- 财务报表 (fin_reports)，主键：report_id
CREATE TABLE fin_reports (
    report_id INT,
    branch_id INT,
    period NVARCHAR(7),
    report_type NVARCHAR(128),
    subject NVARCHAR(128),
    amount DECIMAL(18,2),
    asset DECIMAL(18,2),
    liability DECIMAL(18,2),
    revenue DECIMAL(18,2),
    cost DECIMAL(18,2),
    profit DECIMAL(18,2),
    loan_amt DECIMAL(18,2),
    deposit_amt DECIMAL(18,2)
);

-- 部门 (departments)，主键：dept_id
CREATE TABLE departments (
    dept_id INT,
    dept_name NVARCHAR(128),
    parent_dept_id INT,
    cost_center NVARCHAR(128),
    budget_cost DECIMAL(18,2)
);

-- 员工 (employees)，主键：emp_id
CREATE TABLE employees (
    emp_id INT,
    emp_name NVARCHAR(128),
    gender NVARCHAR(128),
    birth_date DATETIME2(0),
    dept_id INT,
    manager_id INT,
    position NVARCHAR(128),
    job_level INT,
    salary DECIMAL(18,2),
    hire_date DATETIME2(0),
    leave_date DATETIME2(0),
    status NVARCHAR(128),
    city NVARCHAR(128),
    branch_id INT
);

-- 薪酬记录 (salaries)，主键：salary_id
CREATE TABLE salaries (
    salary_id INT,
    emp_id INT,
    base_salary DECIMAL(18,2),
    bonus DECIMAL(18,2),
    allowance DECIMAL(18,2),
    total_salary DECIMAL(18,2),
    effective_date DATETIME2(0),
    pay_month NVARCHAR(7)
);

-- 考勤明细 (attendance)，主键：att_id
CREATE TABLE attendance (
    att_id INT,
    emp_id INT,
    att_date DATETIME2(0),
    check_in DATETIME2(0),
    check_out DATETIME2(0),
    work_hours DECIMAL(12,6),
    overtime_hours DECIMAL(12,6),
    status NVARCHAR(128)
);

-- 休假记录 (leaves)，主键：leave_id
CREATE TABLE leaves (
    leave_id INT,
    emp_id INT,
    leave_type NVARCHAR(128),
    start_date DATETIME2(0),
    end_date DATETIME2(0),
    days INT,
    status NVARCHAR(128)
);

-- 请假申请 (leave_requests)，主键：req_id
CREATE TABLE leave_requests (
    req_id INT,
    emp_id INT,
    leave_type NVARCHAR(128),
    start_date DATETIME2(0),
    end_date DATETIME2(0),
    days INT,
    status NVARCHAR(128),
    apply_date DATETIME2(0)
);

-- 绩效考核 (performance)，主键：perf_id
CREATE TABLE performance (
    perf_id INT,
    emp_id INT,
    period NVARCHAR(7),
    score DECIMAL(12,6),
    rating NVARCHAR(128),
    review_date DATETIME2(0)
);

-- 人事异动 (emp_changes)，主键：change_id
CREATE TABLE emp_changes (
    change_id INT,
    emp_id INT,
    change_type NVARCHAR(128),
    change_date DATETIME2(0),
    old_dept_id INT,
    new_dept_id INT,
    old_salary DECIMAL(18,2),
    new_salary DECIMAL(18,2),
    old_position NVARCHAR(128),
    new_position NVARCHAR(128)
);

-- 培训记录 (training_records)，主键：record_id
CREATE TABLE training_records (
    record_id INT,
    emp_id INT,
    course_name NVARCHAR(128),
    train_date DATETIME2(0),
    hours DECIMAL(12,6),
    score DECIMAL(12,6),
    cost DECIMAL(18,2),
    status NVARCHAR(128)
);

-- 招聘需求 (recruitment)，主键：req_id
CREATE TABLE recruitment (
    req_id INT,
    dept_id INT,
    position NVARCHAR(128),
    headcount INT,
    status NVARCHAR(128),
    channel NVARCHAR(128),
    open_date DATETIME2(0),
    close_date DATETIME2(0),
    apply_cnt INT,
    offer_cnt INT,
    hired_cnt INT,
    offer_salary DECIMAL(18,2),
    channel_cost DECIMAL(18,2)
);

-- 项目 (projects)，主键：project_id
CREATE TABLE projects (
    project_id INT,
    project_name NVARCHAR(128),
    dept_id INT,
    start_date DATETIME2(0),
    end_date DATETIME2(0),
    budget DECIMAL(18,2),
    cost DECIMAL(18,2),
    revenue DECIMAL(18,2),
    status NVARCHAR(128)
);

-- 项目成员投入 (project_assignments)，主键：assign_id
CREATE TABLE project_assignments (
    assign_id INT,
    project_id INT,
    emp_id INT,
    allocation_pct DECIMAL(12,6),
    role NVARCHAR(128)
);

-- 工资单 (payroll)，主键：payroll_id
CREATE TABLE payroll (
    payroll_id INT,
    emp_id INT,
    dept_id INT,
    pay_month NVARCHAR(7),
    pay_date DATETIME2(0),
    gross_pay DECIMAL(18,2),
    net_pay DECIMAL(18,2),
    tax DECIMAL(18,2),
    social_insurance DECIMAL(18,2),
    pay_amount DECIMAL(18,2),
    pay_method NVARCHAR(128)
);

